import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# ---------- Custom CUDA kernel for 1D Average Pooling ----------
avgpool_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avgpool_kernel(const float* input, float* output, int batch_size, int nchannels, int input_length, int kernel_size, int stride, int padding) {
    int padded_len = input_length + 2 * padding;
    int out_len = (padded_len - kernel_size) / stride + 1;
    if (out_len <= 0) return;

    int total_out_elements = batch_size * nchannels * out_len;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_out_elements) {
        int b = idx / (nchannels * out_len);
        int rem = idx % (nchannels * out_len);
        int c = rem / out_len;
        int o = rem % out_len;

        int start = o * stride + padding;
        int count = (start + kernel_size <= padded_len) ? kernel_size : (padded_len - start);
        float sum = 0.0f;
        for (int k = 0; k < count; ++k) {
            int input_idx = start + k;
            if (input_idx < input_length) {
                sum += input[b * nchannels * input_length + c * input_length + input_idx];
            }
        }
        output[idx] = sum / static_cast<float>(count);
    }
}

torch::Tensor avg_pool_cuda(int kernel_size, int stride, int padding, int in_channels, int input_length, int batch_size, int nchannels) {
    auto padded_len = input_length + 2 * padding;
    int out_len = (padded_len - kernel_size) / stride + 1;
    if (out_len <= 0) {
        auto out_shape = {batch_size, in_channels, 0};
        auto out = torch::zeros(out_shape, dtype=torch.float32);
        return out;
    }
    auto out = torch::zeros({batch_size, in_channels, out_len}, dtype=torch.float32);
    const int block_size = 256;
    const int num_blocks = (batch_size * nchannels * out_len + block_size - 1) / block_size;
    avgpool_kernel<<<num_blocks, block_size>>>(
        reinterpret_cast<const float*>(input.data_ptr()),
        reinterpret_cast<float*>(out.data_ptr()),
        batch_size, nchannels, input_length, kernel_size, stride, padding
    );
    return out;
}
"""

# ---------- C++ declaration for avg_pool_cuda ----------
avgpool_cpp_source = (
    "torch::Tensor avg_pool_cuda(int kernel_size, int stride, int padding, int in_channels, int input_length, int batch_size, int nchannels);"
)

# ---------- Load the custom CUDA operator ----------
avg_pool = load_inline(
    name="avg_pool",
    cpp_sources=avgpool_cpp_source,
    cuda_sources=avgpool_kernel_source,
    functions=["avg_pool_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Custom elementwise addition (FP32) ----------
elementwise_add_source = """
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
